import{_ as o,c as t,o as i,ah as l}from"./chunks/framework.Ch_PcVtW.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART1/1/0_context_summary.md","filePath":"scripts/output/PART1/1/0_context_summary.md"}'),r={name:"scripts/output/PART1/1/0_context_summary.md"};function a(c,e,d,n,s,_){return i(),t("div",null,[...e[0]||(e[0]=[l('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1）本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1）本篇主题与主要内容概述&quot;">​</a></h2><p>本文以BMSG成立四周年及进入第五年为背景，围绕SKY-HI对公司经营、艺人成长与行业改革的思考展开。文章重点介绍BMSG“人生优先”“不扼杀才能”的理念，以及BE:FIRST、MAZZEL、BMSG POSSE等项目的发展路径；同时讨论领导者如何在发挥个人号召力与保持组织开放之间取得平衡，如何通过明确愿景、价值观和人才培养建立企业文化。文章还展望“NO NO GIRLS”“THE LAST PIECE”等项目，并强调BMSG的独立性、自主性，以及通过娱乐改善社会、改变日本及东亚音乐行业的长期目标。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2）人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2）人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物与团体名称</strong>：SKY-HI、Novel Core、Aile The Shota、BE:FIRST、MAZZEL、BMSG POSSE、ちゃんみな及成员姓名须统一采用官方中文或日文写法。</li><li><strong>项目与作品名</strong>：<code>THE FIRST</code>、<code>No No Girls</code>、<code>THE LAST PIECE</code>、<code>BMSG FES&#39;24</code>、<code>D.U.N.K.</code>、<code>THE GAME CENTER</code>、<code>Shining One</code>、<code>Mainstream</code>等应保留英文，并统一大小写、引号和斜体规则。</li><li><strong>行业术语</strong>：<code>IP</code>、<code>A&amp;R</code>、<code>CxO</code>、<code>growth</code>、<code>humble</code>、<code>training/trainee</code>、<code>producer</code>等，建议保留英文并补充常用中文释义。</li><li><strong>企业理念的准确性</strong>：<code>Be MySelf Group</code>、<code>才能を殺さないために</code>、<code>4 Values</code>及“革命的、真面目、想像力、成長欲”属于品牌核心表达，不宜意译过度。</li><li><strong>敏感社会议题</strong>：文中涉及性别不平等、外貌主义、偶像产业化、粉丝欲望、行业“潜规则”、前所属事务所等内容，需保持原文批判力度，避免扩大为事实指控。</li><li><strong>人物评价边界</strong>：关于“雇われ社长”、其他公司幕后支持、利益被抽取等表述，应明确保留为SKY-HI的观点，避免译成客观断言。</li><li><strong>语气层次</strong>：管理与战略部分理性、严谨；谈及艺人和员工时亲切、坦率；涉及回忆、玩笑和自嘲时应保留轻松感。</li><li><strong>原文疑似排版或录入问题</strong>：如“なりま先日”“そんたく”“まずサウナサウナ”“3一つ目”“トレーー”等，翻译前应依据上下文校订，不宜机械直译。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3）翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3）翻译时建议重点&quot;">​</a></h2><ul><li>采用“出版物访谈体”：叙述部分客观清晰，SKY-HI第一人称发言保留口语感，但避免过度网络化。</li><li>明确区分<strong>编者说明、采访提问与人物回答</strong>，维持原文标题层级和段落节奏。</li><li>“人生ファースト”建议译为“人生优先”，并在首次出现时结合上下文解释其核心含义：人的成长先于短期成绩。</li><li>“人間的成長”不要简单译为“个人成长”，应根据语境译为“人格与人生层面的成长”或“人的整体成长”。</li><li>“一発屋”可译为“一曲走红后昙花一现”或“一发屋”，首次出现可补充解释。</li><li>“風通しの良さ”建议译为“组织的开放度/沟通畅通”，不要直译成“通风良好”。</li><li>“カリスマ性の発揮”与“humble”应分别体现号召力、权威感与谦逊、易接近之间的张力。</li><li>“勝ち方にこだわる”“生き方にこだわる”等重复句式应保留其宣言感和节奏。</li><li>对“社会を善くしたい”“エンタテインメントは社会を善くする”等核心主张应保持直接、有力，不宜弱化为“带来积极影响”。</li><li>涉及音乐业务时，优先使用行业通行译法；英文术语可保留原文，并在首次出现处加中文注释。</li></ul>',6)])])}const h=o(r,[["render",a]]);export{S as __pageData,h as default};
